import figma from "figma";

const instance = figma.selectedInstance;

const attr = (name, value) => {
  if (value === undefined || value === false) return "";
  if (value === true) return ` ${name}`;
  if (typeof value === "number") return ` ${name}={${value}}`;
  return value.startsWith("{") ? ` ${name}=${value}` : ` ${name}="${value}"`;
};
const codeOf = (node) =>
  node && node.type === "INSTANCE" ? node.executeTemplate().example : undefined;

const title = instance.getString("Title");
const message = instance.getString("Message");
const icon = codeOf(instance.getInstanceSwap("Icon"));
const action = instance.getBoolean("Show action")
  ? codeOf(instance.findInstance("Action"))
  : undefined;

export default {
  id: "Empty state",
  example: figma.code`<HvEmptyState${attr("title", title)}${attr("message", message)}${icon ? figma.code` icon={${icon}}` : ""}${action ? figma.code` action={${action}}` : ""} />`,
  imports: ['import { HvEmptyState } from "@pentaho/uikit-react-core";'],
  metadata: { nestable: true },
};
